package net.officefloor.hq.app.patron;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and a person named. */
public class ValidatePatron {
    public void validate(@RequestBody PatronRequest request, Out<PatronRequest> body) throws InvalidPatronException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPatronException("Sign in before naming patrons.");
        }
        if (request.patronId() == null) {
            throw new InvalidPatronException("Choose a person to name as a patron.");
        }
        body.set(new PatronRequest(request.user().trim(), request.patronId()));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { live, useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { recentSettledSum, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { patronsKey, usePatrons } from './patrons';
import type { Patron } from './patrons';

/** A person's patrons (their names, sorted), their backing — the patrons' settled figures over their SETTLED claims
 *  dated within the 90 days up to and including the sheet's today (see recentSettledSum); 0.00 with none — and the
 *  picker that names one more. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const claims = live(useClaims(sheetId).data ?? [], people, today);
  const rates = useRates(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
