p='src/main/frontend/features/rates/rates.ts'
s=open(p).read()
anchor="/** A sum of figures at most the cap"
add='''/** 100.00 split equally among n patrons in the order named: each share 100.00 / n rounded to two decimals half to
 *  even, the first-named taking the remainder (100.00 minus the shares added up). */
export function patronShares(n: number): string[] {
  if (n <= 0) return [];
  const count = BigInt(n);
  let share = 10000n / count;
  const rest = 10000n % count;
  if (rest * 2n > count || (rest * 2n === count && share % 2n === 1n)) share += 1n;
  return Array.from({ length: n }, (_, i) => fromCents(i === 0 ? 10000n - share * (count - 1n) : share));
}

/** Figures each weighted by a share: the sum of figure times share divided by 100, rounded half to even (exact, in
 *  integers); n/a figures are skipped. */
export function sharedSum(parts: { figure: string; share: string }[]): string {
  const scaled = parts.filter((p) => p.figure !== 'n/a')
    .reduce((total, p) => total + toCents(p.figure) * toCents(p.share), 0n); // in 1/10000 of a cent
  const sign = scaled < 0n ? -1n : 1n;
  const abs = scaled * sign;
  let cents = abs / 10000n;
  const rest = abs % 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return fromCents(cents * sign);
}

'''
assert anchor in s
s=s.replace(anchor,add+anchor,1)
open(p,'w').write(s)

p='src/main/frontend/features/patrons/patrons.slot.tsx'
s=open(p).read()
old_start=s.index("/** A person's patrons (their names")
old_end=s.index("  const [chosen, setChosen]")
new='''/** A person's patrons, each as <name> <share> sorted by name — 100.00 split equally in the order they were named, the
 *  first-named taking the remainder (see patronShares) — their backing — each patron's settled figures over their
 *  SETTLED claims dated within the 90 days up to and including the sheet's today (see recentSettledSum) times their
 *  share / 100, added up and rounded half to even (see sharedSum); 0.00 with none — and the picker that names one more. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const claims = live(useClaims(sheetId).data ?? [], people, today);
  const rates = useRates(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  // the server lists each person's patrons in the order they were named
  const named = (usePatrons(sheetId).data ?? [])
    .filter((p) => p.personId === person.id)
    .map((p) => people.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined);
  const shares = patronShares(named.length);
  const patrons = named
    .map((p, i) => ({ person: p, share: shares[i] }))
    .sort((a, b) => (a.person.name < b.person.name ? -1 : a.person.name > b.person.name ? 1 : 0));
  const backing = sharedSum(patrons.map((p) => ({
    figure: recentSettledSum([p.person], claims, rates, today, floor, late),
    share: p.share,
  })));
'''
